        // SAINAimingSettings
        { "Override Global Part Weights", "전역 부위 가중치 덮어쓰기" },
        { "Use this bot type's own aim target weights instead of the global ones.", "전역 값 대신 이 봇 종류 전용 조준 부위 가중치를 씀." },
        { "Only used when Override Global Part Weights is enabled.", "'전역 부위 가중치 덮어쓰기'가 켜져 있을 때만 사용." },
        { "Can Aim for Headshots", "헤드샷 조준 가능" },
        { "Can Aim for Headshots - Percentage Chance", "헤드샷 조준 가능 - 확률(%)" },
        { "Distance Aim Time Multiplier", "거리별 조준 시간 배율" },
        { "Multiplies the time a bot takes to aim based on distance. So higher values will cause bots to take longer to aim depending on distance.", "거리에 따라 봇의 조준 시간에 곱함. 높을수록 거리에 따라 조준이 오래 걸림." },
        { "Angle Aim Time Multiplier", "각도별 조준 시간 배율" },
        { "Multiplies the time a bot takes to aim based on the angle they have to turn to line up a shot. So higher values will cause bots to take longer to aim depending on the angle to turn.", "사격선을 맞추려고 돌아야 하는 각도에 따라 봇의 조준 시간에 곱함. 높을수록 도는 각도에 따라 조준이 오래 걸림." },
        { "Faster CQB Reactions", "근접전(CQB) 빠른 반응" },
        { "Sets whether this bot reacts and aims faster before being able to shoot at close ranges", "이 봇이 근거리에서 더 빨리 반응하고 조준해서 쏠 수 있는지 설정" },
        { "Faster CQB Reactions Max Distance", "근접전 빠른 반응 최대 거리" },
        { "Max distance a bot can react faster for Faster CQB Reactions. Scales with distance.", "근접전 빠른 반응이 적용되는 최대 거리. 거리에 비례." },
        { "Max distance a bot can react faster for Faster CQB Reactions. Scales with distance.Example: If Max distance is set to 20 meters, and an enemy is 10 meters away. they will react 2x as fast as usual, or if an enemy is 15 meters away, they will react 1.5x as fast as usual. If the enemy is at 20 meters or further, nothing will happen.", "근접전 빠른 반응이 적용되는 최대 거리. 거리에 비례. 예: 최대 거리 20m, 적이 10m면 평소보다 2배 빨리 반응, 15m면 1.5배. 20m 이상이면 효과 없음." },
        { "Faster CQB Reactions Minimum Speed", "근접전 빠른 반응 최소 시간" },
        { "Absolute minimum speed (in seconds) that bot can react and shoot", "봇이 반응해서 쏠 수 있는 절대 최소 시간(초)" },
        { "Max Aiming Upgrade By Time", "시간에 따른 최대 조준 향상" },
        { "VANILLA EFT CONFIG VALUE : Lower = Better. How much to cap this bots aim improvement based on time. 0.25 means they will be able to multiply their aim offset by 0.25x when aiming. Making their shots more accurate", "바닐라 EFT 설정값: 낮을수록 좋음. 시간이 지나며 좋아지는 조준의 상한. 0.25면 조준할 때 조준 오차에 0.25배까지 곱할 수 있어 더 정확해짐" },
        { "Distance To Not Scatter Aim", "탄 퍼짐 없는 거리" },
        { "VANILLA EFT CONFIG VALUE : If an enemy is closer than this distance, ignore scatter.", "바닐라 EFT 설정값: 적이 이 거리보다 가까우면 탄 퍼짐 무시." },
        { "VANILLA EFT CONFIG VALUE : Scatter Multiplier - Moving", "바닐라 EFT 설정값: 탄 퍼짐 배율 - 이동 중" },
        { "Max Aim Time", "최대 조준 시간" },
        { "VANILLA EFT CONFIG VALUE :  A cap on how long it will take this bot to finish aiming at a target, and begin shooting.", "바닐라 EFT 설정값: 이 봇이 목표 조준을 끝내고 사격을 시작하기까지 걸리는 시간의 상한." },
        { "VANILLA EFT CONFIG VALUE : Hit Reaction Recovery Time", "바닐라 EFT 설정값: 피격 반응 회복 시간" },
        { "How much time it takes to recover a bot's aim when they get hit by a bullet", "봇이 총에 맞았을 때 조준을 회복하는 데 걸리는 시간" },
        { "VANILLA EFT CONFIG VALUE : Hit Aim Time Penalty Seconds - Min", "바닐라 EFT 설정값: 피격 시 조준 시간 불이익(초) - 최소" },
        { "VANILLA EFT CONFIG VALUE : Hit Aim Time Penalty Seconds - Max", "바닐라 EFT 설정값: 피격 시 조준 시간 불이익(초) - 최대" },
        { "VANILLA EFT CONFIG VALUE : Enemy First Contact Reaction Delay", "바닐라 EFT 설정값: 적 첫 접촉 반응 지연" },
        // SAINCoreSettings
        { "Vision", "시야" },
        { "Field of View", "시야각" },
        { "Base Vision Distance", "기본 시야 거리" },
        { "Gain Sight Coeficient", "발견 계수" },
        { "Default EFT Config. Affects how quickly this bot will notice their enemies. Small changes to this have dramatic affects on bot vision speed.", "EFT 기본 설정. 이 봇이 적을 얼마나 빨리 알아채는지. 조금만 바꿔도 발견 속도가 크게 변함." },
        { "Aim and Shoot", "조준과 사격" },
        { "Accuracy Speed", "조준 속도" },
        { "Default EFT Config. Affects how quickly this bot will aim at targets.", "EFT 기본 설정. 이 봇이 목표를 얼마나 빨리 조준하는지." },
        { "Default EFT Config. I do not know what this does exactly.", "EFT 기본 설정. (원작자도) 정확히 뭘 하는지 모름." },
        { "Modifies the distance that this bot can hear sounds", "이 봇이 소리를 들을 수 있는 거리를 조절" },
